import {
	computed,
	defineComponent,
	h,
	inject,
	onBeforeUnmount,
	onMounted,
	provide,
	ref,
	reactive,
	useId,
	type ComputedRef,
	type InjectionKey,
	type PropType,
	type VNode,
} from 'vue';
import {
	CHART_INITIAL_DIMENSION,
	buildChartThemeCss,
	chartStyleKeys,
	computeChartLayout,
	findChartNearestIndex,
	getChartAreaPathD,
	getChartBaselineY,
	getChartBarRects,
	getChartLegendItems,
	getChartPathD,
	getChartTooltipEntries,
	getChartTooltipPosition,
} from '../lib/core';
import type { ChartConfig, ChartDatum, ChartLayout, ChartLegendItem, ChartSeriesItem, ChartTooltipEntry, ChartType } from '../lib/core';
import styles from './chart.module.scss';

interface ChartContextValue {
	config: ChartConfig;
	layout: ChartLayout;
	data: ChartDatum[];
	activeIndex: number | null;
}

type ChartContext = ComputedRef<ChartContextValue>;

const ChartContextKey: InjectionKey<ChartContext> = Symbol('tile-chart');

/**
 * 读取图表上下文 (必须在 ChartContainer 内使用)
 */
function useChart(): ChartContext {
	const context = inject(ChartContextKey);
	if (!context) {
		throw new Error('图表子组件必须在 <ChartContainer /> 内使用');
	}
	return context;
}

export const ChartStyle = defineComponent({
	name: 'ChartStyle',
	props: {
		id: { type: String, required: true },
		config: { type: Object as PropType<ChartConfig>, required: true },
	},
	setup(props) {
		const css = computed(() => buildChartThemeCss(props.id, props.config));

		return () => {
			if (!css.value) {
				return null;
			}
			return h('style', { innerHTML: css.value });
		};
	},
});

export const ChartContainer = defineComponent({
	name: 'ChartContainer',
	inheritAttrs: false,
	props: {
		config: { type: Object as PropType<ChartConfig>, required: true },
		title: { type: String, default: undefined },
		tabIndex: { type: Number, default: undefined },
		data: { type: Array as PropType<ChartDatum[]>, default: () => [] },
		xKey: { type: String, default: 'x' },
		series: { type: Array as PropType<ChartSeriesItem[]>, default: undefined },
		type: { type: String as PropType<ChartType>, default: 'line' },
		initialDimension: { type: Object as PropType<{ width: number; height: number }>, default: undefined },
		showLegend: { type: Boolean, default: true },
		showTooltip: { type: Boolean, default: true },
		showGrid: { type: Boolean, default: true },
		showAxis: { type: Boolean, default: true },
	},
	setup(props, { slots, attrs }) {
		const containerRef = ref<HTMLElement | null>(null);
		const size = reactive({ width: props.initialDimension?.width ?? CHART_INITIAL_DIMENSION.width, height: props.initialDimension?.height ?? CHART_INITIAL_DIMENSION.height });
		const activeIndex = ref<number | null>(null);
		const keyboardActive = ref(false);
		const mousePosition = reactive({ x: 0, y: 0 });
		const chartId = `chart-${useId()}`;

		let observer: ResizeObserver | null = null;

		onMounted(() => {
			const element = containerRef.value;
			if (!element) {
				return;
			}
			observer = new ResizeObserver((entries) => {
				for (const entry of entries) {
					const { width } = entry.contentRect;
					if (width > 0) {
						// 高度固定：容器高度由 SVG 内容撑开，若跟随容器高度会形成正反馈循环导致无限放大
						size.width = width;
					}
				}
			});
			observer.observe(element);
		});

		onBeforeUnmount(() => {
			observer?.disconnect();
			observer = null;
		});

		const layout = computed(() =>
			computeChartLayout({
				config: props.config,
				data: props.data,
				series: props.series ?? [],
				xKey: props.xKey,
				type: props.type,
				width: size.width,
				height: size.height,
				cssVariableScope: chartId,
			}),
		);

		const context = computed<ChartContextValue>(() => ({
			config: props.config,
			layout: layout.value,
			data: props.data,
			activeIndex: activeIndex.value,
		}));

		provide(ChartContextKey, context);

		const entries = computed(() => getChartTooltipEntries(layout.value, props.config, props.data, activeIndex.value));
		const legendItems = computed(() => getChartLegendItems(layout.value));
		const tooltipX = computed(() => (activeIndex.value !== null ? (layout.value.xTickX[activeIndex.value] ?? 0) : 0));
		const tooltipLabel = computed(() => (activeIndex.value !== null ? layout.value.xLabels[activeIndex.value] : null));

		function handleMouseMove(event: MouseEvent) {
			const svg = event.currentTarget as SVGSVGElement;
			const rect = svg.getBoundingClientRect();
			const x = ((event.clientX - rect.left) / rect.width) * layout.value.width;
			const y = ((event.clientY - rect.top) / rect.height) * layout.value.height;
			keyboardActive.value = false;
			mousePosition.x = x;
			mousePosition.y = y;
			activeIndex.value = findChartNearestIndex(layout.value, x);
		}

		function handleMouseLeave() {
			activeIndex.value = null;
		}

		function callEventHandler(handler: unknown, event: Event) {
			for (const current of Array.isArray(handler) ? handler : [handler]) {
				if (typeof current === 'function') current(event);
			}
		}

		function handleKeyDown(event: KeyboardEvent) {
			callEventHandler(attrs.onKeydown, event);
			const tabIndex = props.tabIndex ?? attrs.tabindex;
			if (event.defaultPrevented || tabIndex === undefined || Number(tabIndex) < 0 || event.target !== event.currentTarget) return;
			if (event.key === 'Escape') {
				keyboardActive.value = false;
				activeIndex.value = null;
				return;
			}
			if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
			const count = layout.value.xLabels.length;
			if (count === 0) return;
			event.preventDefault();
			keyboardActive.value = true;
			if (activeIndex.value === null) activeIndex.value = event.key === 'ArrowLeft' ? count - 1 : 0;
			else activeIndex.value = Math.min(count - 1, Math.max(0, activeIndex.value + (event.key === 'ArrowLeft' ? -1 : 1)));
		}

		return () => {
			const l = layout.value;
			const userClass = attrs.class;
			const restAttrs = { ...attrs };
			for (const key of ['class', 'title', 'aria-label', 'aria-labelledby', 'aria-describedby', 'tabindex', 'tabIndex', 'onKeydown']) delete restAttrs[key];
			const title = props.title;
			const ariaLabel = typeof attrs['aria-label'] === 'string' ? attrs['aria-label'] : undefined;
			const ariaLabelledBy = typeof attrs['aria-labelledby'] === 'string' ? attrs['aria-labelledby'] : undefined;
			const ariaDescribedBy = typeof attrs['aria-describedby'] === 'string' ? attrs['aria-describedby'] : undefined;
			const tabIndex = props.tabIndex ?? attrs.tabindex;
			const svgLabel = ariaLabel ?? (ariaLabelledBy ? undefined : (title ?? 'Chart'));
			const statusText =
				keyboardActive.value && activeIndex.value !== null
					? [tooltipLabel.value, ...entries.value.map((entry) => `${entry.name} ${entry.value.toLocaleString()}`)].join(', ')
					: '';

			const children: any[] = [h(ChartStyle, { id: chartId, config: props.config })];

			const svgChildren: any[] = title ? [h('title', title)] : [];

			if (props.showGrid) {
				for (const y of l.yTickY) {
					svgChildren.push(h('line', { key: `y-${y}`, class: styles[chartStyleKeys.gridLine], x1: l.padding.left, x2: l.width - l.padding.right, y1: y, y2: y }));
				}
				for (const x of l.xTickX) {
					svgChildren.push(h('line', { key: `x-${x}`, class: styles[chartStyleKeys.gridLine], x1: x, x2: x, y1: l.padding.top, y2: l.height - l.padding.bottom }));
				}
			}

			if (props.showAxis) {
				l.xLabels.forEach((label, index) => {
					svgChildren.push(
						h(
							'text',
							{
								key: `label-${index}`,
								x: l.xTickX[index],
								y: l.height - l.padding.bottom / 2,
								'text-anchor': 'middle',
								'dominant-baseline': 'middle',
								'font-size': '10',
							},
							String(label),
						),
					);
				});
			}

			l.series.forEach((item, seriesIndex) => {
				if (item.type === 'bar') {
					const barSeriesCount = l.series.filter((s) => s.type === 'bar').length;
					const rects = getChartBarRects(l, seriesIndex, barSeriesCount);
					const bars = rects.map((rect) =>
						h('rect', { key: rect.index, 'data-index': rect.index, x: rect.x, y: rect.y, width: rect.width, height: rect.height, fill: item.color, rx: '2' }),
					);
					svgChildren.push(h('g', { key: item.key, 'data-series': item.key, 'data-type': item.type }, bars));
					return;
				}

				const path = item.type === 'area' ? getChartAreaPathD(item.points, getChartBaselineY(l)) : getChartPathD(item.points);
				const group: any[] = [];
				if (item.type === 'area') {
					group.push(h('path', { 'data-area': '', d: path, fill: item.color, 'fill-opacity': '0.2' }));
				}
				group.push(
					h('path', { d: getChartPathD(item.points), fill: 'none', stroke: item.color, 'stroke-width': '2', 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }),
				);
				for (const point of item.points) {
					group.push(h('circle', { key: point.index, 'data-index': point.index, cx: point.x, cy: point.y, r: '2.5', fill: item.color }));
				}
				svgChildren.push(h('g', { key: item.key, 'data-series': item.key, 'data-type': item.type }, group));
			});

			if (props.showTooltip && activeIndex.value !== null) {
				svgChildren.push(
					h('line', {
						x1: tooltipX.value,
						x2: tooltipX.value,
						y1: l.padding.top,
						y2: l.height - l.padding.bottom,
						stroke: 'currentColor',
						'stroke-dasharray': '3 3',
						opacity: '0.4',
					}),
				);
			}

			children.push(
				h(
					'svg',
					{
						class: styles[chartStyleKeys.surface],
						width: l.width,
						height: l.height,
						viewBox: `0 0 ${l.width} ${l.height}`,
						role: 'img',
						'aria-label': svgLabel,
						'aria-labelledby': ariaLabelledBy,
						'aria-describedby': ariaDescribedBy,
						onMousemove: handleMouseMove,
						onMouseleave: handleMouseLeave,
					},
					svgChildren,
				),
			);

			if (props.showTooltip && activeIndex.value !== null) {
				children.push(
					h(ChartTooltipContent, {
						active: true,
						payload: entries.value,
						label: tooltipLabel.value,
						class: styles[chartStyleKeys.tooltip],
						style: {
							position: 'absolute',
							...Object.fromEntries(Object.entries(getChartTooltipPosition(layout.value, mousePosition.x, mousePosition.y)).map(([k, v]) => [k, `${v}px`])),
						},
					}),
				);
			}

			if (props.showLegend) {
				children.push(h(ChartLegendContent, { payload: legendItems.value }));
			}

			children.push(
				h(
					'div',
					{
						'data-slot': 'chart-status',
						role: 'status',
						'aria-live': 'polite',
						'aria-atomic': 'true',
						style: {
							position: 'absolute',
							width: '1px',
							height: '1px',
							padding: '0',
							margin: '-1px',
							overflow: 'hidden',
							clipPath: 'inset(50%)',
							whiteSpace: 'nowrap',
							border: '0',
						},
					},
					statusText,
				),
			);

			if (slots.default) {
				children.push(slots.default(context.value));
			}

			return h(
				'div',
				{
					...restAttrs,
					ref: containerRef,
					'data-slot': 'chart',
					'data-chart': chartId,
					'data-active-index': activeIndex.value ?? undefined,
					class: [styles[chartStyleKeys.root], userClass],
					title,
					'aria-label': ariaLabel,
					'aria-labelledby': ariaLabelledBy,
					'aria-describedby': ariaDescribedBy,
					tabindex: tabIndex,
					onKeydown: handleKeyDown,
				},
				children,
			);
		};
	},
});

export const ChartTooltipContent = defineComponent({
	name: 'ChartTooltipContent',
	props: {
		active: { type: Boolean, default: false },
		payload: { type: Array as PropType<ChartTooltipEntry[]>, default: () => [] },
		indicator: { type: String as PropType<'line' | 'dot' | 'dashed'>, default: 'dot' },
		hideLabel: { type: Boolean, default: false },
		hideIndicator: { type: Boolean, default: false },
		label: { type: [String, Number, Object] as PropType<string | number | null>, default: null },
		color: { type: String, default: undefined },
		formatter: { type: Function as PropType<(value: number, name: string, item: ChartTooltipEntry, index: number) => VNode | string | number | null>, default: undefined },
		labelFormatter: { type: Function as PropType<(value: unknown, payload: ChartTooltipEntry[]) => VNode | string | number | null>, default: undefined },
	},
	setup(props, { attrs }) {
		const context = useChart();

		return () => {
			const items = props.payload ?? [];
			const config = context.value.config;

			if (!props.active || items.length === 0) {
				return null;
			}

			const userClass = attrs.class;
			const restAttrs = { ...attrs };
			delete restAttrs.class;

			const formattedLabel = props.labelFormatter ? props.labelFormatter(props.label, items) : String(props.label ?? '');
			const labelNode = !props.hideLabel && props.label != null ? h('div', { class: styles[chartStyleKeys.tooltipLabel] }, [formattedLabel]) : null;

			const itemNodes = items.map((item, index) => {
				const itemConfig = config[item.dataKey];
				const indicatorColor = props.color ?? item.color;

				const indicatorNode = props.hideIndicator
					? null
					: h('span', {
							class: styles[chartStyleKeys.tooltipIndicator],
							'data-indicator': props.indicator,
							style: { backgroundColor: indicatorColor, borderColor: indicatorColor },
						});

				const valueNode =
					props.formatter && item.value !== undefined
						? [props.formatter(item.value as number, item.name, item, index)]
						: [h('div', { class: styles[chartStyleKeys.tooltipItemValue] }, typeof item.value === 'number' ? item.value.toLocaleString() : String(item.value))];

				return h('div', { key: index, class: styles[chartStyleKeys.tooltipItem], 'data-indicator': props.indicator }, [
					indicatorNode,
					h('div', { class: styles[chartStyleKeys.tooltipItemName] }, itemConfig?.label ?? item.name),
					valueNode,
				]);
			});

			return h('div', { ...restAttrs, class: [userClass] }, [labelNode, h('div', { class: styles[chartStyleKeys.tooltipGrid] }, itemNodes)]);
		};
	},
});

export const ChartLegendContent = defineComponent({
	name: 'ChartLegendContent',
	props: {
		payload: { type: Array as PropType<ChartLegendItem[]>, default: () => [] },
		hideIcon: { type: Boolean, default: false },
		verticalAlign: { type: String as PropType<'top' | 'bottom'>, default: 'bottom' },
	},
	setup(props, { attrs }) {
		return () => {
			const items = props.payload ?? [];
			if (items.length === 0) {
				return null;
			}

			const userClass = attrs.class;
			const restAttrs = { ...attrs };
			delete restAttrs.class;

			const itemNodes = items.map((item, index) =>
				h('div', { key: index, class: styles[chartStyleKeys.legendItem] }, [
					props.hideIcon ? null : h('span', { class: styles[chartStyleKeys.legendSwatch], style: { backgroundColor: item.color } }),
					item.name,
				]),
			);

			return h('div', { ...restAttrs, 'data-align': props.verticalAlign, class: [styles[chartStyleKeys.legend], userClass] }, itemNodes);
		};
	},
});

export const ChartTooltip = defineComponent({
	name: 'ChartTooltip',
	setup(_props, { slots, attrs }) {
		const context = useChart();

		return () => {
			const { layout, config, data, activeIndex } = context.value;
			const entries = getChartTooltipEntries(layout, config, data, activeIndex);
			const label = activeIndex !== null ? layout.xLabels[activeIndex] : null;

			if (slots.default) {
				return slots.default({ active: activeIndex !== null, payload: entries, label });
			}

			return h(ChartTooltipContent, { ...attrs, active: activeIndex !== null, payload: entries, label });
		};
	},
});

export const ChartLegend = defineComponent({
	name: 'ChartLegend',
	setup(_props, { attrs }) {
		const context = useChart();

		return () => h(ChartLegendContent, { ...attrs, payload: getChartLegendItems(context.value.layout) });
	},
});

export default ChartContainer;

@use '../../../styles/variables/colors' as *;

// 图表根容器
.root {
	position: relative;
	display: flex;
	width: 100%;
	aspect-ratio: 16 / 9;
	flex-direction: column;
	justify-content: center;
	font-size: var(--tile-chart-font-size, $text-xs);
	color: var(--tile-chart-muted-foreground, $muted-foreground);
}

// 绘图画布
.surface {
	overflow: visible;

	text {
		fill: var(--tile-chart-muted-foreground, $muted-foreground);
	}
}

// 网格线
.gridLine {
	stroke: var(--tile-chart-grid-color, $border);
	stroke-opacity: var(--tile-chart-grid-opacity, 0.5);
	stroke-dasharray: var(--tile-chart-grid-dasharray, 4 4);
}

// 坐标轴线
.axisLine {
	stroke: var(--tile-chart-axis-color, $border);
}

// 图例容器
.legend {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: $spacing-4;
	padding-top: $spacing-3;

	&[data-align='top'] {
		padding-top: 0;
		padding-bottom: $spacing-3;
	}
}

// 图例条目
.legendItem {
	display: flex;
	align-items: center;
	gap: $spacing-1_5;
	color: var(--tile-chart-muted-foreground, $muted-foreground);
}

// 图例色块
.legendSwatch {
	width: 0.5rem;
	height: 0.5rem;
	flex-shrink: 0;
	border-radius: $radius-xs;
}

// Tooltip 容器
.tooltip {
	pointer-events: none;
	display: grid;
	min-width: 8rem;
	align-items: start;
	gap: $spacing-1_5;
	border: 1px solid var(--tile-chart-tooltip-border, color-mix(in srgb, $border 50%, transparent));
	border-radius: var(--tile-chart-tooltip-radius, $radius);
	background-color: var(--tile-chart-tooltip-background, $popover);
	padding: $spacing-1_5 $spacing-2_5;
	color: var(--tile-chart-tooltip-foreground, $popover-foreground);
	font-size: var(--tile-chart-font-size, $text-xs);
	box-shadow: var(--tile-chart-tooltip-shadow, $shadow-lg);
}

// Tooltip 标签
.tooltipLabel {
	font-weight: $font-medium;
}

// Tooltip 条目网格
.tooltipGrid {
	display: grid;
	gap: $spacing-1_5;
}

// Tooltip 单条条目
.tooltipItem {
	display: flex;
	width: 100%;
	flex-wrap: wrap;
	align-items: stretch;
	gap: $spacing-2;

	&[data-indicator='dot'] {
		align-items: center;
	}
}

// Tooltip 条目名称
.tooltipItemName {
	color: var(--tile-chart-muted-foreground, $muted-foreground);
}

// Tooltip 条目数值
.tooltipItemValue {
	font-family: $font-mono;
	font-weight: $font-medium;
	color: var(--tile-chart-foreground, $foreground);
	font-variant-numeric: tabular-nums;
}

// Tooltip 指示器
.tooltipIndicator {
	flex-shrink: 0;
	border-radius: $radius-xs;

	&[data-indicator='dot'] {
		width: 0.625rem;
		height: 0.625rem;
	}

	&[data-indicator='line'] {
		width: 0.25rem;
		height: 1rem;
	}

	&[data-indicator='dashed'] {
		width: 0;
		border: 1.5px dashed currentColor;
		background: transparent;
	}
}
